L2_1 = {}
L2_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@2#Talk"
L2_1.m_CutScenProcessKey = 2
L2_1.m_CutScenID = 3500208
L2_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "CHILD_EXTRA_NULL_NULL"
L2_1.m_Talk_KOREA = "엄마, 나 이 약 먹으면 이제 기침 안 해?"
L2_1.m_fTalkTime = 0.03
L2_1.m_Talk_JPN = "ママ、この薬を飲めば咳が止まるの？"
L2_1.m_Talk_ENG = "Mommy, am I going to stop coughing after I drink this syrup?"
L2_1.m_Talk_TWN = "媽媽，我把這個藥吃掉就不會咳嗽了嗎？"
L2_1.m_Talk_THA = "แม่จ๋า ถ้าหนูดื่มนี่แล้วจะหยุดไอเหรอ?"
L2_1.m_Talk_VTN = "Mẹ ơi, con sẽ hết ho sau khi uống siro này phải không?"
L2_1.m_Talk_SCN = "妈妈，我吃这个药，就不会咳嗽了吗？"
L2_1.m_Talk_DEU = "Mama, werde ich aufhören zu husten, nachdem ich diesen Sirup getrunken habe?"
L2_1.m_Talk_FRA = "Maman, est-ce que j'arrêterai de tousser si je bois ce sirop ?"
L3_1 = {}
L3_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 3500208
L3_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "MOTHER_EXTRA_NULL_NULL"
L3_1.m_Talk_KOREA = "그럼. 비 맞으면 안 되니까 어서 가자, 응?"
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "そうよ。雨に濡れると風邪を引いちゃうから、早く行きましょう。"
L3_1.m_Talk_ENG = "That's right, sweetie. Now let's hurry back home. We wouldn't want to get caught in the rain."
L3_1.m_Talk_TWN = "是啊，不能淋到雨，我們快回去吧！"
L3_1.m_Talk_THA = "ใช่แล้วลูกจ๋า รีบกลับบ้านกันเถอะนะ เราจะได้ไม่ต้องไปติดอยู่ในรถไฟกัน"
L3_1.m_Talk_VTN = "Đúng vậy, con yêu. Bây giờ chúng ta hãy nhanh chóng trở về nhà nếu không muốn bị mắc mưa."
L3_1.m_Talk_SCN = "当然了。在下雨之前赶快回去吧。"
L3_1.m_Talk_DEU = "Genau, mein Schatz. Jetzt lass uns schnell nach Hause zurückkehren. Wir möchten nicht im Regen stehen."
L3_1.m_Talk_FRA = "Bien sûr, ma chérie. Et maintenant, dépêchons-nous de rentrer avant qu'il se mette à pleuvoir."
L4_1 = {}
L4_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 3500208
L4_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "CHILD_EXTRA_NULL_NULL"
L4_1.m_Talk_KOREA = "응! 제프티 아저씨들이 아빠한테도 자랑하랬어!"
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "うん！　ジェフティのおじさんたちがパパにも自慢していいって言ったの！"
L4_1.m_Talk_ENG = "Okay! Those nice Jehuty uncles told me to tell daddy about them too!"
L4_1.m_Talk_TWN = "嗯！傑夫堤叔叔還叫我跟爸爸炫耀呢！"
L4_1.m_Talk_THA = "โอเค! คุณลุงเจฮูตีใจดีบอกให้หนูเล่าให้พ่อฟังด้วย!"
L4_1.m_Talk_VTN = "Được chứ! Những các chú Jehuty tốt bụng đó đã bảo con cũng phải kể cho bố nghe về họ!"
L4_1.m_Talk_SCN = "嗯！杰普提的叔叔们说，我回去之后也要告诉爸爸！"
L4_1.m_Talk_DEU = "Na gut! Diese netten Jehuty-Herren haben mir gesagt, dass ich dir davon erzählen soll!"
L4_1.m_Talk_FRA = "D'accord ! Les monsieurs de Jehuty m'ont dit de parler d'eux à papa, aussi !"
