L9_1 = {}
L9_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 3500208
L9_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Talk_KOREA = "<color=#ff3636>프로토타입들은 전부 자멸해 버렸어. 로그를 검토해 보니 기동 직후 자의적으로 합선을 일으켰더군.</color>"
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "<color=#ff3636>プロトタイプは全て自滅してしまった。ログを確認してみたら、起動直後に自分の意志でショートを起こしたそうだ。</color>"
L9_1.m_Talk_ENG = "<color=#ff3636>All the prototypes self-destructed. According to the log, they voluntarily short-circuited themselves immediately upon activation.</color>"
L9_1.m_Talk_TWN = "<color=#ff3636>樣品已經全都自行銷毀。 查看歷程，發現是啟動後隨機引起短路。</color>"
L9_1.m_Talk_THA = "<color=#ff3636>ตัวต้นแบบทั้งหมดทำลายตัวเองไปแล้ว บันทึกระบุว่า พวกเขาสมัครใจลัดวงจรตัวเองในทันทีที่เริ่มทำงาน</color>"
L9_1.m_Talk_VTN = "<color=#ff3636>Tất cả các nguyên mẫu đều tự hủy. Theo nhật ký, chúng tự đoản mạch ngay sau khi kích hoạt.</color>"
L9_1.m_Talk_SCN = "<color=#ff3636>原型机全都自毁了。查询日志发现是因为短路问题。</color>"
L9_1.m_Talk_DEU = "<color=#ff3636>Alle Prototypen haben sich selbst zerstört. Laut Protokoll haben sie sich sofort nach der Aktivierung freiwillig kurzgeschlossen.</color>"
L9_1.m_Talk_FRA = "<color=#ff3636>Tous les prototypes se sont auto-détruits. D'après le journal d'activité, ils se sont volontairement court-circuités juste après leur activation.</color>"
L10_1 = {}
L10_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 3500208
L10_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Talk_KOREA = "하나 남아 있습니다. 성능도 우리가 원했던 기준을 충족하고 있어요."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "一つだけ残っています。性能も私たちが決めた基準を満たしています。"
L10_1.m_Talk_ENG = "There's still one left. And its performance more than meets the standards we desire."
L10_1.m_Talk_TWN = "還剩一個，性能也符合我們想要的標準。"
L10_1.m_Talk_THA = "แต่ยังเหลืออยู่ตัวหนึ่งนะ และก็ทำผลงานได้ดีกว่ามาตรฐานที่เราคาดหวังกันด้วย"
L10_1.m_Talk_VTN = "Vẫn còn một chiếc nữa. Và hiệu suất của nó còn vượt cả các tiêu chuẩn mà chúng ta mong muốn."
L10_1.m_Talk_SCN = "还剩下一个。性能也能满足我们的标准。"
L10_1.m_Talk_DEU = "Es ist noch einer übrig. Und seine Leistung wird den von uns gewünschten Standards mehr als gerecht."
L10_1.m_Talk_FRA = "Il en reste encore un, qui dispose des performances souhaitées."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 3500208
L11_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Talk_KOREA = "<color=#ff3636>저건 결함품이야. 탑재시켰다간 사람들한테 총구를 돌릴 결함품일 뿐이라고.</color>"
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "<color=#ff3636>あれは欠陥品だよ。搭載させると人々に銃口を向ける欠陥品にすぎない。</color>"
L11_1.m_Talk_ENG = "<color=#ff3636>That one's defective. I'll only put our people in danger if we load that thing up.</color>"
L11_1.m_Talk_TWN = "<color=#ff3636>那是瑕疵品。是搭載後會將槍口轉向人的瑕疵品。</color>"
L11_1.m_Talk_THA = "<color=#ff3636>ตัวนั้นเป็นของบกพร่องนะ ถ้าโหลดตัวนั้นละก็รังแต่จะอันตรายกับคนของเรา</color>"
L11_1.m_Talk_VTN = "<color=#ff3636>Cái đó bị lỗi. Tôi sẽ chỉ khiến người của chúng ta gặp nguy hiểm nếu sử dụng nó.</color>"
L11_1.m_Talk_SCN = "<color=#ff3636>但那个是残次品。是搭载后可能会将枪口对准人们的残次品。</color>"
L11_1.m_Talk_DEU = "<color=#ff3636>Das ist Mangelware. Wenn wir das da installieren, werden sich die Geschosse gegen uns richten.</color>"
L11_1.m_Talk_FRA = "<color=#ff3636>Non, celui-ci est défectueux. Si on le charge, il ne fera que mettre nos hommes en danger.</color>"
L12_1 = {}
L12_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 3500208
L12_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Talk_KOREA = "저건 사람과 다르지 않아요. 어떻게 가르치냐에 따라 충분히 교정할 수 있습니다."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "あれは人と同じです。教え方によって十分改善できます。"
L12_1.m_Talk_ENG = "But it's no different from a person. We can correct its behavior with ample education."
L12_1.m_Talk_TWN = "她就跟人一樣，只要好好教她，是可以矯正的。"
L12_1.m_Talk_THA = "แต่ก็เหมือนมนุษย์แหละ เราแก้ไขพฤติกรรมมันได้ด้วยการศึกษาที่เพียงพอ"
L12_1.m_Talk_VTN = "Nhưng nó không khác gì một con người. Chúng ta có thể điều chỉnh hành vi của nó bằng sự giáo dục phong phú."
L12_1.m_Talk_SCN = "但她和人没什么不同。通过指导完全可以获得矫正。"
L12_1.m_Talk_DEU = "Aber es ist nicht anders als bei einer Person. Wir können sein Verhalten mit umfassender Aufklärung korrigieren."
L12_1.m_Talk_FRA = "Mais quelle différence avec un individu normal ? Nous pourrons toujours corriger son comportement avec une éducation adaptée."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 3500208
L13_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Talk_KOREA = "<color=#ff3636>우리가 왜 여기 모였는지 잊었나? 당장 폐기시켜!</color>"
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "<color=#ff3636>我々がここに集まった理由を忘れたのか？　今すぐ廃棄しろ！</color>"
L13_1.m_Talk_ENG = "<color=#ff3636>Did you forget why we're here in the first place? Get rid of it right away!</color>"
L13_1.m_Talk_TWN = "<color=#ff3636>你忘記我們爲什麼會在這裡嗎？立刻將她報廢！</color>"
L13_1.m_Talk_THA = "<color=#ff3636>นี่ลืมไปแล้วรึไงว่าเรามาทำอะไรกัน? กำจัดมันทิ้งเดี๋ยวนี้เลยนะ!</color>"
L13_1.m_Talk_VTN = "<color=#ff3636>Cô đã quên lý do tại sao chúng ta ở đây ngay từ đầu sao? Loại bỏ nó ngay lập tức! </color>"
L13_1.m_Talk_SCN = "<color=#ff3636>你忘了我们为什么会在这里吗？立即废弃掉！</color>"
L13_1.m_Talk_DEU = "<color=#ff3636>Habt ihr vergessen, warum wir überhaupt hier sind? Werdet es sofort los!</color>"
L13_1.m_Talk_FRA = "<color=#ff3636>Tu as déjà oublié pourquoi nous sommes ici ? Débarrasse-toi de lui tout de suite !</color>"
L14_1 = {}
L14_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 3500208
L14_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Talk_KOREA = "<color=#ff3636>우리가 사람을 만들려고 했나? 우리한테 필요한 건 무기야!</color>"
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "<color=#ff3636>人を作ろうとしたのではない！　我々に必要なものは武器だ！</color>"
L14_1.m_Talk_ENG = "<color=#ff3636>We're not trying to build a person! What we need is a weapon!</color>"
L14_1.m_Talk_TWN = "<color=#ff3636>我們想製造的是人嗎？我們需要的是武器！</color>"
L14_1.m_Talk_THA = "<color=#ff3636>เราไม่ได้พยายามจะสร้างมนุษย์กันนะ! ที่เราต้องการคืออาวุธต่างหาก!</color>"
L14_1.m_Talk_VTN = "<color=#ff3636>Chúng ta không cố gắng xây dựng một con người! Thứ chúng ta cần là vũ khí!</color>"
L14_1.m_Talk_SCN = "<color=#ff3636>我们可不是为了制造人类！我们需要的是武器！</color>"
L14_1.m_Talk_DEU = "<color=#ff3636>Wir versuchen nicht, einen Menschen zu erschaffen! Was wir brauchen, ist eine Waffe!"
L14_1.m_Talk_FRA = "<color=#ff3636>Nous n'essayons pas de créer des individus. C'est d'armes dont nous avons besoin !</color>"
L15_1 = {}
L15_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 3500208
L15_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Talk_KOREA = "<color=#ff3636>사람들 대신 전쟁터에서 싸우다 죽어 줄 무기!</color>"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "<color=#ff3636>人の代わりに戦場で戦い、死んでくれる武器なのだ！</color>"
L15_1.m_Talk_ENG = "<color=#ff3636>A weapon to fight and die in our stead on the battlefield!</color>"
L15_1.m_Talk_TWN = "<color=#ff3636>代替人類在戰場上戰死的武器！</color>"
L15_1.m_Talk_THA = "<color=#ff3636>อาวุธที่จะสู้และตายแทนเราในสนามรบน่ะ</color>"
L15_1.m_Talk_VTN = "<color=#ff3636>Một vũ khí để chiến đấu và chết thay cho chúng ta trên chiến trường!</color>"
L15_1.m_Talk_SCN = "<color=#ff3636>是可以替人在战场上战斗和牺牲的武器！</color>"
L15_1.m_Talk_DEU = "<color=#ff3636>Eine Waffe, die an unserer Stelle auf dem Schlachtfeld kämpft und dann stirbt!</color>"
L15_1.m_Talk_FRA = "<color=#ff3636>Des armes qui puissent combattre et mourir pour nous sur le champ de bataille !</color>"
L16_1 = {}
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 3500208
L16_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L16_1.m_bWaitClick = false
L16_1.m_fWaitTime = 0
L17_1 = {}
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 3500208
L17_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
