L21_1 = {}
L21_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 3500208
L21_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L21_1.m_Pos = "C"
L21_1.m_Talk_KOREA = "대출 상담은 현재 중단 중이니 다음에 다시 걸어 주십시오."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "現在貸付けの相談を行っておりません。また今度かけ直してください。"
L21_1.m_Talk_ENG = "We have currently suspended loan applications. Please call us at a later time."
L21_1.m_Talk_TWN = "目前暫時不受理資金洽詢，請下次再打。"
L21_1.m_Talk_THA = "ขณะนี้เราอยู่ระหว่างระงับการสมัครกู้ยืม โปรดโทรมาใหม่ภายหลังนะคะ"
L21_1.m_Talk_VTN = "Chúng tôi hiện đã tạm ngưng việc tiếp nhận các đơn xin vay. Vui lòng gọi cho chúng tôi sau nhé."
L21_1.m_Talk_SCN = "现在暂时无法进行贷款商谈，请下次再拨。"
L21_1.m_Talk_DEU = "Wir haben derzeit die Beratung zu den Kreditanträgen ausgesetzt. Bitte rufen Sie uns zu einem späteren Zeitpunkt an."
L21_1.m_Talk_FRA = "Nous ne faisons pas crédit pour le moment. Veuillez nous recontacter ultérieurement."
