L23_1 = {}
L23_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 3500208
L23_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L23_1.m_Talk_KOREA = "<color=#ffd34c>이상하군요. 제 단말기를 방전시킬 만큼 연락하던 분은 그쪽이셨을 텐데요.</color>"
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "<color=#ffd34c>おかしいですね。私の端末を放電させるほど連絡してきたのはそちらだったと思いますが。</color>"
L23_1.m_Talk_ENG = "<color=#ffd34c>That's weird. I mean, you're the one who kept calling me 'til my battery ran out.</color>"
L23_1.m_Talk_TWN = "<color=#ffd34c>真奇怪，把我的電話打到快沒電的人應該是你吧？</color>"
L23_1.m_Talk_THA = "<color=#ffd34c>แปลกแฮะ คือ เธอต่างหากที่โทรมาจนฉันแบตหมดน่ะ</color>"
L23_1.m_Talk_VTN = "<color=#ffd34c>Điều đó thật kỳ lạ. Ý tôi là cô là người đã gọi liên tục cho đến khi tôi cháy máy. </color>"
L23_1.m_Talk_SCN = "<color=#ffd34c>奇怪。明明是那边先给我打了无数个电话，怎么会接不通。</color>"
L23_1.m_Talk_DEU = "<color=#ffd34c>Das ist seltsam. Ich meine, Sie haben mich die ganze Zeit angerufen, bis mein Akku leer war.</color>"
L23_1.m_Talk_FRA = "<color=#ffd34c>Vraiment ? Étrange... C'est pourtant vous qui m'avez harcelée de coups de fil jusqu'à ce que ma batterie rende l'âme...</color>"
L24_1 = {}
L24_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 3500208
L24_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L24_1.m_bWaitClick = true
