L24_1.m_Face = "UNIT_HATE"
L24_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L24_1.m_Pos = "C"
L24_1.m_Talk_KOREA = "……코핀 컴퍼니?"
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "……コフィンカンパニー？"
L24_1.m_Talk_ENG = "…Coffin Company?"
L24_1.m_Talk_TWN = "……科芬公司？"
L24_1.m_Talk_THA = "... บริษัทคอฟฟินเหรอคะ?"
L24_1.m_Talk_VTN = "… Công ty Coffin?"
L24_1.m_Talk_SCN = "……科芬公司？"
L24_1.m_Talk_DEU = "Die Coffin Company?"
L24_1.m_Talk_FRA = "... La Compagnie Coffin ?"
