L27_1 = {}
L27_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 3500208
L27_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_HATE"
L27_1.m_StartFXSoundName = "FX_CUTSCEN_BEEP"
L27_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L27_1.m_Pos = "R"
L27_1.m_Talk_KOREA = "이제야 연락이 닿았군요. 왜 계속 답신이 없었습니까."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "やっと連絡が取れましたね。なぜ今まで返事がなかったのですか。"
L27_1.m_Talk_ENG = "So I've finally gotten through to you. What took you so long to respond?"
L27_1.m_Talk_TWN = "終於聯絡上，爲什麼一直不回電？"
L27_1.m_Talk_THA = "ในที่สุดฉันก็ติดต่อคุณได้ ทำไมชักช้านักคะ?"
L27_1.m_Talk_VTN = "Cuối cùng tôi cũng liên hệ được với cô. Điều gì khiến cô mất nhiều thời gian như vậy để trả lời?"
L27_1.m_Talk_SCN = "现在才联系到你们。为什么一直没给我回信？"
L27_1.m_Talk_DEU = "Ich habe Sie endlich erreicht. Warum haben Sie so lange gebraucht, um zu antworten?"
L27_1.m_Talk_FRA = "Vous voilà enfin. Qu'est-ce qui vous a pris autant de temps ?"
L28_1 = {}
L28_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 3500208
L28_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L28_1.m_Pos = "L"
L28_1.m_Talk_KOREA = "저희도 사업하면서 적을 많이 만든 입장입니다. 더 많은 적을 만들지도 모르는 결정에는 더 신중히 움직여야죠."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "こちらも事業をしながら敵をたくさん作ってしまった立場です。より多くの敵を作ってしまう可能性があるなら、慎重に動くべきでしょう。"
L28_1.m_Talk_ENG = "As you may understand, this line of business inevitably involves making a lot of enemies. Extra caution is warranted in making a decision that could get us even more enemies."
L28_1.m_Talk_TWN = "我們在做生意的過程中也製造不少敵人，對於要不要製造更多敵人，當然要慎重考慮囉。"
L28_1.m_Talk_THA = "อย่างที่คุณน่าจะพอเข้าใจนะคะว่า ธุรกิจสายนี้ต้องไปข้องแวะกับการสร้างศัตรูเยอะแยะอย่างหลีกเลี่ยงไม่ได้ ถ้าต้องตัดสินใจอะไรที่อาจทำให้เรามีศัตรูมากขึ้น สิ่งที่ช่วยรับประกันให้เราได้ก็มีแต่ความระมัดระวังเป็นพิเศษค่ะ"
L28_1.m_Talk_VTN = "Như cô có thể hiểu, ngành kinh doanh này chắc chắn có thể gây ra nhiều kẻ thù. Cần hết sức thận trọng khi đưa ra quyết định có thể khiến chúng tôi gặp nhiều kẻ thù hơn."
L28_1.m_Talk_SCN = "我们在事业上升的过程中已经树立了不少敌人，所以对待可能带来更多敌人的决定，也会更加慎重。"
L28_1.m_Talk_DEU = "Wie Sie vielleicht verstehen, bedeutet dieser Geschäftszweig zwangsläufig, sich viele Feinde zu machen. Besondere Vorsicht ist geboten, wenn man eine Entscheidung trifft, die uns noch mehr Feinde einbringen könnte."
L28_1.m_Talk_FRA = "Dans notre secteur d'activité, on se fait vite des ennemis. Chaque décision doit être mûrement réfléchie et pour cela, nous prenons le temps nécessaire."
L29_1 = {}
L29_1.m_CutScenKey_Talk = "HORIZON_ACT2_STAGE3_START@29#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 3500208
L29_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L29_1.m_Pos = "L"
L29_1.m_Talk_KOREA = "연락을 드리기 직전까지 내부에서 수많은 의사결정 과정을 거쳤다는 점, 양해 부탁드립니다."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "連絡を差し上げる直前まで、内部ではとても長い意思決定の過程を経ていたことをご理解いただければ幸いです。"
L29_1.m_Talk_ENG = "As such, our decision makers had to consider many factors through extensive discussions until we decided to return your call. I hope you understand."
L29_1.m_Talk_TWN = "我們內部必須先經過無數次的討論才能打給你，這點還請見諒。"
L29_1.m_Talk_THA = "เช่น ผู้มีอำนาจตัดสินใจของเราต้องพิจารณาปัจจัยหลายประการผ่านการอภิปรายที่รอบด้านจนกว่าเราจะตัดสินใจโทรกลับมาหาคุณ หวังว่าคุณจะเข้าใจนะคะ"
L30_1 = "Do đó, những người ra quyết định của chúng tôi đã phải cân nhắc nhiều yếu tố cho đến khi chúng tôi quyết định gọi lại cho cô. Tôi hy vọng cô hiểu."
L29_1.m_Talk_VTN = L30_1
L30_1 = "在联系你之前，我们内部也需要经过统一意见的过程。所以请你谅解。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Daher mussten unsere Entscheidungsträger in ausführlichen Diskussionen viele Faktoren berücksichtigen, bis wir uns entschieden haben, Sie zurückzurufen. Ich hoffe, Sie verstehen."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Il nous a fallu considérer une variété de facteurs et engager de nombreuses discussions avant d'être sûrs de pouvoir vous répondre. Je suis sûre que vous comprendrez."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "HORIZON_ACT2_STAGE3_START@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 30
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3500208
L30_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L30_1.m_Pos = "R"
L31_1 = "그 과정에서 고려했던 조건 중에 저에 대한 내용도 포함되어 있었습니까?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "その過程で考慮した条件の中に、私に関する内容も含まれていましたか？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Was there something about me that was one of the factors in your discussions?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "我也包含在你們討論的內容中嗎？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ในบรรดาปัจจัยต่างๆ ที่คุณอภิปราบนั่นมีอะไรเกี่ยวกับฉันสักข้อมั้ยคะ?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Các cô có đề cập đến điều gì về tôi khi thảo luận không?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "在考虑过程中也包含对我怎么处理的内容吗？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Gab es etwas über mich, das einer der Faktoren in Ihren Diskussionen war?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Des discussions ? Y'avait-il quelque chose à mon propos qui méritait d'être discuté ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "HORIZON_ACT2_STAGE3_START@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3500208
L31_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "UNIT_LAUGH"
L31_1.m_Face = L32_1
L31_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L31_1.m_Pos = "L"
L32_1 = "사내 기밀사항이기 때문에 공유해 드리기 어렵겠군요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "社内機密事項ですので共有することは難しいです。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I'm afraid I cannot divulge the details of such sensitive company matters to you."
L31_1.m_Talk_ENG = L32_1
L32_1 = "討論內容屬公司機密，無法對外公開。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เกรงว่าฉันจะเปิดเผยรายละเอียดที่มีความละเอียดอ่อนต่อบริษัทขนาดนั้นให้คุณทราบไม่ได้นะคะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi e rằng tôi không thể tiết lộ chi tiết về những vấn đề nhạy cảm như vậy của công ty với cô."
L31_1.m_Talk_VTN = L32_1
L32_1 = "这是公司内部的保密事项，所以无法告知。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich fürchte, ich kann Ihnen die Einzelheiten solch sensibler Unternehmensangelegenheiten nicht preisgeben."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Désolée, mais je ne peux pas vous divulguer ce genre d'informations. C'est confidentiel."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "HORIZON_ACT2_STAGE3_START@32#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3500208
L32_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_IDLE"
L32_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L32_1.m_Pos = "L"
L33_1 = "상황이 급박하게 돌아가고 있으니 바로 본론으로 들어가겠습니다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "緊迫した状況ですので、さっそく本題に入りましょう。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Given the urgency of the situation, I'll cut right to the chase."
L32_1.m_Talk_ENG = L33_1
L33_1 = "現在情況有點緊急，請恕我直接進入正題。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ด้วยความเร่งด่วนของสถานการณ์แล้วนี่ ฉันขอเข้าเรื่องเลยนะคะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Với tình hình cấp bách hiện tại, tôi sẽ nói thẳng."
L32_1.m_Talk_VTN = L33_1
L33_1 = "现在事态紧急，直接进入正题吧。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Angesichts der Dringlichkeit der Situation komme ich gleich zur Sache."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Compte tenu de l'urgence, je vais être directe."
L32_1.m_Talk_FRA = L33_1
