L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3500208
L34_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L34_1.m_bWaitClick = true
