L34_1.m_Face = "UNIT_IDLE"
L34_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L34_1.m_Pos = "C"
L34_1.m_bCharHologramEffect = true
L35_1 = "당신이 요구했던 윌버란 인물의 소재지를 확보했습니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "あなたが要請したウィルバーという人物の居場所を特定しました。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "We've identified the whereabouts of this Wilbur person you requested."
L34_1.m_Talk_ENG = L35_1
L35_1 = "你要我們找的韋爾伯的下落，目前已經掌握到。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เราระบุที่อยู่ของคนที่ชื่อวิลเบอร์ได้ตามที่คุณขอมาแล้วนะคะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Chúng tôi đã xác định được nơi ở của gã Wilbur mà cô yêu cầu."
L34_1.m_Talk_VTN = L35_1
L35_1 = "我们已经查到你要找的那个，叫韦尔伯的人的地址。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Wir haben den Aufenthaltsort von diesem gewissen Wilbur ermittelt."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Nous avons identifié la position de Wilbur, la personne que vous cherchez."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "HORIZON_ACT2_STAGE3_START@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3500208
L35_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "사실 여부 및 교차 검증도 이미 끝마친 상태입니다."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "事実確認、交差検証もすでに済んでいます。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "We've already cross-referenced the veracity of this intel."
L35_1.m_Talk_ENG = L36_1
L36_1 = "也已經多方查證，證實資訊無誤。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "และเราก็ตรวจสอบความถูกต้องของข่าวกรองนี้กับกับแหล่งอ้างอิงอื่นๆ แล้วด้วย"
L35_1.m_Talk_THA = L36_1
L36_1 = "Chúng tôi đã tham khảo chéo tính xác thực của thông tin này."
L35_1.m_Talk_VTN = L36_1
L36_1 = "而且为了验证准确性，已经完成交叉确认。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Wir haben die Richtigkeit dieser Informationen bereits doppelt gegengeprüft."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Nos informateurs sont formels, et cette information a déjà été vérifiée."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "HORIZON_ACT2_STAGE3_START@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3500208
L36_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "반가운 소식이군요. 그 자는 어디에 있습니까."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "嬉しい知らせですね。その者はどこにいますか。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "That's good to hear. So where is he?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "這真是個好消息，那他現在在哪裡？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ค่อยโล่งใจหน่อยค่ะ แล้วเขาอยู่ที่ไหนคะ?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Tốt quá. Vậy anh ta đang ở đâu?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "真是不错的消息。那他在哪。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Das ist gut zu hören. Wo ist er also?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Je suis contente de l'entendre. Alors, où est-il ?"
L36_1.m_Talk_FRA = L37_1
