L40_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L41_1 = "현재 그는, 제프티 바이오테크의 대표직을 수행 중입니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "彼は現在、ジェフティ・バイオテックの代表を務めています。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "He's currently serving as the CEO of Jehuty Biotech."
L40_1.m_Talk_ENG = L41_1
L41_1 = "他現在是傑夫堤生物科技的代表。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ตอนนี้เขาทำหน้าที่เป็นซีอีโอของเจฮูตีไบโอเทคค่ะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Anh ta hiện đang giữ chức vụ CEO của Jehuty Biotech."
L40_1.m_Talk_VTN = L41_1
L41_1 = "他现在是杰普提生物科技的老板。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Aktuell führt er die Rolle des Vorsitzenden von Jehuty Biotech aus."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Wilbur est le Président de Jehuty Biotech."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = 41
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3500208
L41_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L41_1.m_bWaitClick = false
L41_1.m_fWaitTime = 1
L41_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L42_1 = {}
L43_1 = "HORIZON_ACT2_STAGE3_START@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3500208
L42_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "<color=#ffd34c>두려워하지 마십시오, 여러분. 저희는 제프티 바이오테크에서 파견한 의료 봉사단입니다.</color>"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "<color=#ffd34c>皆様、恐れることはありません。我々はジェフティ・バイオテックから派遣された医療奉仕団です。</color>"
L42_1.m_Talk_JPN = L43_1
L43_1 = "<color=#ffd34c>Do not be afraid, everyone. We are a medical relief team dispatched from Jehuty Biotech.</color>"
L42_1.m_Talk_ENG = L43_1
L43_1 = "<color=#ffd34c>大家請不要害怕，我們是傑夫堤生物科技派來的義診團隊。</color>"
L42_1.m_Talk_TWN = L43_1
L43_1 = "<color=#ffd34c>ทุกคนอย่าได้กลัวไป เราเป็นทีมบรรเทาทุกข์ทางการแพทย์ที่ได้รับมอบหมายจากเจฮูตีไบโอเทค</color>"
L42_1.m_Talk_THA = L43_1
L43_1 = "<color=#ffd34c>Đừng sợ, tất cả mọi người. Chúng tôi là một nhóm cứu trợ y tế được điều động từ Jehuty Biotech.</color>"
L42_1.m_Talk_VTN = L43_1
L43_1 = "<color=#ffd34c>请不要害怕，各位。我们是杰普提生物科技派遣的医疗服务团。</color>"
L42_1.m_Talk_SCN = L43_1
L43_1 = "<color=#ffd34c>Habt keine Angst, allerseits. Wir sind ein medizinisches Hilfsteam, das von Jehuty Biotech entsandt wurde.</color>"
L42_1.m_Talk_DEU = L43_1
L43_1 = "<color=#ffd34c>N'ayez pas peur, nous sommes une équipe médicale déployée spécialement par Jehuty Biotech.</color>"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "HORIZON_ACT2_STAGE3_START@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3500208
L43_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "<color=#ffd34c>지금 광장에서 무상 진료를 시행하고 있습니다. 의약품도 무상으로 지급하고 있사오니…….</color>"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "<color=#ffd34c>現在、広場で無料診療を行っております。医薬品も無料配布しておりますので……</color>"
L43_1.m_Talk_JPN = L44_1
L44_1 = "<color=#ffd34c>We are currently providing free medical examinations at the plaza. We're also offering medical supplies free of charge…</color>"
L43_1.m_Talk_ENG = L44_1
L44_1 = "<color=#ffd34c>現在正在廣場提供義診，藥物也免費提供……</color>"
L43_1.m_Talk_TWN = L44_1
L44_1 = "<color=#ffd34c>เรากำลังให้ยาไปทดลองใช้ฟรีที่ลานกลางเมือง และยังมีของใช้ทางการแพทย์ให้ฟรีด้วย...</color>"
L43_1.m_Talk_THA = L44_1
L44_1 = "<color=#ffd34c>Chúng tôi hiện đang khám bệnh miễn phí tại quảng trường. Chúng tôi cũng cung cấp nguồn vật tư y tế miễn phí…</color>"
L43_1.m_Talk_VTN = L44_1
L44_1 = "<color=#ffd34c>现在正在广场提供免费身体检查服务。还有免费赠送的药品……</color>"
L43_1.m_Talk_SCN = L44_1
L44_1 = "<color=#ffd34c>Wir bieten derzeit kostenlose medizinische Untersuchungen auf dem Platz an. Wir bieten auch kostenlose medizinische Versorgung ...</color>"
L43_1.m_Talk_DEU = L44_1
L44_1 = "<color=#ffd34c>Nous offrons actuellement des examens médicaux gratuits à tous les citoyens, ainsi que du matériel médical aux personnes qui en ont besoin...</color>"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "HORIZON_ACT2_STAGE3_START@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3500208
L44_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L45_1 = "호라이즌, 듣고 계신가요?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ホライズン、聞いていますか？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "You still with me, Horizon?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "地平線，你有在聽嗎？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ยังอยู่ในสายรึเปล่าคะฮอไรซัน?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cô vẫn đang nghe chứ, Horizon?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "地平线，你还在听吗？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Horizon, hören Sie?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Vous êtes toujours avec moi, Horizon ?"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "HORIZON_ACT2_STAGE3_START@45#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3500208
L45_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L46_1 = "……잠시 후에 다시 연락해 주십시오. 급한 용무가 생겼습니다."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "……後ほど改めてご連絡ください。急用ができました。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "…Please call me again in a moment. Something urgent has come up."
L45_1.m_Talk_ENG = L46_1
L46_1 = "……請稍後再跟我聯絡，我現在有急事。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "... อีกครู่ช่วยโทรมาหาฉันใหม่นะคะ พอดีมีเรื่องด่วนเข้ามาค่ะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "… Vui lòng gọi lại cho tôi trong giây lát. Có việc khẩn cấp đã phát sinh."
L45_1.m_Talk_VTN = L46_1
L46_1 = "……请你稍后再联系。我现在有急事。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Bitte rufen Sie mich gleich noch einmal an. Es ist etwas Dringendes dazwischengekommen."
L45_1.m_Talk_DEU = L46_1
L46_1 = "... Rappelez-moi plus tard. J'ai une urgence."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
