L6_1 = "HORIZON_ACT2_STAGE3_START@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3500208
L5_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "그림을 그릴 줄 아는 휴먼은 싫다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "絵が描けるヒューマンは嫌いだ。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I do not like the artist human."
L5_1.m_Talk_ENG = L6_1
L6_1 = "討厭會畫畫的人類。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ฉันไม่ชอบศิลปินมนุษย์เลยค่ะ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tôi không thích con người là nghệ sĩ."
L5_1.m_Talk_VTN = L6_1
L6_1 = "我讨厌会画画的人类。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ich mag den Maler-Menschen nicht."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Je n'aime pas l'humaine artiste."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "HORIZON_ACT2_STAGE3_START@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3500208
L6_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "보고 있으면, 오류가 발생한다."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "見ていると、エラーが発生する。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Watching her causes errors in me."
L6_1.m_Talk_ENG = L7_1
L7_1 = "看著的話會發生錯誤。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "มองเธอฉันก็เออร์เรอร์แล้วค่ะ"
L6_1.m_Talk_THA = L7_1
L7_1 = "Nếu nhìn cô ấy, sẽ gây ra sự cố trong tôi."
L6_1.m_Talk_VTN = L7_1
L7_1 = "如果看着她，就会发生故障。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ihr zuzuschauen, verursacht Fehler in mir."
L6_1.m_Talk_DEU = L7_1
L7_1 = "La regarder provoque des erreurs dans mon système."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "HORIZON_ACT2_STAGE3_START@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3500208
L7_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "나를 보고 웃는 휴먼도. 싫다."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "私を見て笑顔になるヒューマンも、嫌いだ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "And the human who smiles at me. I dislike her as well."
L7_1.m_Talk_ENG = L8_1
L8_1 = "也討厭會看著我笑的人類。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แล้วก็มนุษย์คนที่ยิ้มให้ฉันน่ะค่ะ ฉันก็ไม่ชอบเธอเหมือนกัน"
L7_1.m_Talk_THA = L8_1
L8_1 = "Và người mỉm cười với tôi. Tôi cũng không thích cô ấy."
L7_1.m_Talk_VTN = L8_1
L8_1 = "我也讨厌朝我笑的人类。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ich mag auch den Grinse-Menschen nicht."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Je n'aime pas non plus l'humaine qui me regarde en souriant."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
