L13_1 = "대장님. 전달 받은 인상착의와 정확하게 일치합니다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "隊長、情報にあった特徴や服装と正確に一致します。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Sir. She matches the description to a T."
L12_1.m_Talk_ENG = L13_1
L13_1 = "隊長，衣著和長相和描述的一樣。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ท่านครับ เธอตรงกับที่บรรยายเป๊ะเลยครับ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Sếp. Nó khớp với mô tả của T."
L12_1.m_Talk_VTN = L13_1
L13_1 = "组长。她的穿着与我们收到的消息一致。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Kommandant, sie stimmt mit der Beschreibung exakt überein."
L12_1.m_Talk_DEU = L13_1
