L16_1 = "HORIZON_ACT2_STAGE3_START@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 3500208
L15_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L15_1.m_bWaitClick = true
