L16_1 = "MBOSS_HORIZON_NULL_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "L"
L16_1 = "뭐야. 들었던 것보다 훨씬 어리게 생겼네."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "なんだ、聞いていたよりずっと幼いじゃないか。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "What the. She looks a lot younger than we were told."
L15_1.m_Talk_ENG = L16_1
L16_1 = "什麼嘛～年紀看起來比我聽到的還小嘛！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ไรเนี่ย เธอดูเด็กกว่าที่เรารู้มาเยอะเลยนะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Cái gì. Nó trông trẻ hơn rất nhiều so với những gì chúng ta được nghe."
L15_1.m_Talk_VTN = L16_1
L16_1 = "什么嘛，比听说的看起来要小很多。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Huch? Sie sieht viel jünger aus, als uns gesagt wurde."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Quoi ? Elle est drôlement plus jeune que ce qu'on m'avait dit."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "HORIZON_ACT2_STAGE3_START@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3500208
L16_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L16_1.m_bWaitClick = true
