L17_1 = "MBOSS_HORIZON_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "L"
L17_1 = "m_Crash"
L16_1[L17_1] = 15
L17_1 = "저거 건드렸다가 국제법에 저촉되는 거 아닙니까?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "あれに手を出したら犯罪になると思いますが……"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Are you sure we won't be violating any international laws if we mess with her?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "碰她會觸犯國際法吧？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "แน่ใจเหรอครับว่าถ้าไปยุ่งกับเธอนี่เราจะไม่ไปทำผิดกฎหมายระหว่างประเทศข้อไหนเข้า"
L16_1.m_Talk_THA = L17_1
L17_1 = "Anh có chắc chúng ta sẽ không vi phạm bất kỳ luật quốc tế nào nếu chúng ta gây chuyện với nó ở đây không?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "如果我们对她采取行动，会不会受到国际法的制裁？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Bist du dir sicher, dass wir keine internationalen Gesetze verletzen, wenn wir uns mit ihr anlegen?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Vous êtes sûr qu'on ne risque pas d'avoir le droit international aux trousses si on s'en prend à elle ?"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "HORIZON_ACT2_STAGE3_START@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3500208
L17_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "BOSS_HORIZON_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "R"
L18_1 = "국제법이 신경 쓰이면 네 발밑에서 꿈틀거리는 계집애부터 얼른 갖다 버리지 그래."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "法律が気になるなら、まずお前の足元でうずくまっているそいつを捨ててこい。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "If you're so worried about international law, why don't you first go get rid of that girl squirming under your foot?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "你有時間擔心國際法，不如先把腳底下那丫頭帶去丟掉吧。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ถ้ากังวลเรื่องกฎหมายระหว่างประเทศนัก ทำไมไม่จัดการยัยเด็กที่ดิ้นกระแด่วๆ อยู่ใต้เท้าแกไปซะก่อนเลยล่ะ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Nếu đang rất lo lắng về luật pháp quốc tế, tại sao không xử lý con bé đang quấn chân anh trước đi?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "如果担心国际法的话，还是先处理掉在你脚下挣扎的女孩吧。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Wenn du dir solche Sorgen um internationales Recht machst, warum wirst du dann nicht zuerst dieses Mädchen los, das sich unter deinem Fuß windet?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Le droit international ? Si ça t'inquiète tant que ça, commence par te débarrasser de cette mioche sous ton pied."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
