L23_1 = "전신 타박상 및 다발성 골절 확인. 3도 화상과 내출혈 감지."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "全身打撲および多発性骨折を確認。Ⅲ度熱傷と内出血を感知。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Extensive bruises and multiple fractures confirmed. Third-degree burns and internal bleeding detected."
L22_1.m_Talk_ENG = L23_1
L23_1 = "全身挫傷和多處骨折確認。感應到3度燒傷和內出血。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ยืนยันการมีรายช้ำไปทั่วและกระดูกหักหลายแห่ง ตรวจพบแผลไหม้ระดับสามและเลือดออกภายใน"
L22_1.m_Talk_THA = L23_1
L23_1 = "Các vết bầm tím trên diện rộng và nhiều chỗ gãy xương đã được xác nhận. Phát hiện bỏng độ ba và chảy máu trong."
L22_1.m_Talk_VTN = L23_1
L23_1 = "全身有淤血和多处骨折。检测到3度烧伤以及内出血。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ganzkörper-Prellungen und mehrere Brüche bestätigt. Verbrennungen dritten Grades und innere Blutungen festgestellt."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Présence confirmée d'ecchymoses et de fractures multiples. Hémorragies internes et brûlure au 3ème degré détectées."
L22_1.m_Talk_FRA = L23_1
