L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3500208
L27_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_IDLE"
L28_1 = "BOSS_HORIZON_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "R"
L28_1 = "걱정 마라. 죽이진 않았으니까."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "心配するな。殺してはいないから。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Don't worry. She's still breathing."
L27_1.m_Talk_ENG = L28_1
L28_1 = "放心，我們不會要她的命。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ไม่ต้องห่วงน่า เธอยังหายใจอยู่"
L27_1.m_Talk_THA = L28_1
L28_1 = "Đừng lo lắng. Cô ấy vẫn thở."
L27_1.m_Talk_VTN = L28_1
L28_1 = "别担心。我们没杀她。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Mach dir keine Sorgen. Sie atmet noch."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ne t'inquiète pas, elle respire encore."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "HORIZON_ACT2_STAGE3_START@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3500208
L28_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "BOSS_HORIZON_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "R"
L29_1 = "실험 재료로 넘기는 게 우리한텐 더 남는 장사거든."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "実験材料として渡した方が、俺たちにとっては商売になるからな。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "It's a lot more lucrative to turn her over as a test subject, after all."
L28_1.m_Talk_ENG = L29_1
L29_1 = "把她送去當實驗材料，這筆生意對我們比較有利。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ยังไงการส่งเธอไปเป็นตัวทดลองก็กำไรกว่ามาก"
L28_1.m_Talk_THA = L29_1
L29_1 = "Rốt cuộc, biến nó thành vật thí nghiệm sẽ sinh lợi hơn rất nhiều."
L28_1.m_Talk_VTN = L29_1
L29_1 = "因为把她作为试验材料移交对我们来说更划算。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Es ist schließlich viel lukrativer, sie als Testperson abzugeben."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Nous avons bien meilleur intérêt à faire d'elle un sujet d'expérience, après tout."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
