L31_1 = "HORIZON_ACT2_STAGE3_START@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3500208
L30_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "BOSS_HORIZON_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "애초에 어른들이 기다리고 있는데 늦장 부린 네 탓이잖아."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "そもそも大人が待っているのに遅れてきやがったお前のせいじゃないか。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Anyway, this is all your fault for keeping us waiting."
L30_1.m_Talk_ENG = L31_1
L31_1 = "大人們都在等，誰叫你這麼慢呢？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ว่าก็ว่านะ นี่มันความผิดเธอที่ปล่อยให้พวกเรารอไง"
L30_1.m_Talk_THA = L31_1
L31_1 = "Dù sao, đây là lỗi của cô vì đã để chúng tôi chờ đợi."
L30_1.m_Talk_VTN = L31_1
L31_1 = "谁让你来的这么晚，害得我们一直在等。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Wie auch immer, das ist alles deine Schuld, weil du uns warten lassen hast."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Et puis c'est de ta faute, il ne fallait pas nous faire attendre comme ça."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "HORIZON_ACT2_STAGE3_START@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3500208
L31_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "BOSS_HORIZON_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "미리 말해 두겠는데, 이 강화복은 블랙타이드 놈들이 쓰는 것의 개량형이다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "あらかじめ言っておくが、この強化服はブラックタイドの連中が使ってるものの改良型だぞ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "And for the record, this power suit is an upgraded version of what those Black Tide pigs wear."
L31_1.m_Talk_ENG = L32_1
L32_1 = "別說我沒提醒你，這套強化服可是用黑潮那些傢伙在用的去改良的。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "และก็บอกให้เอาบุญนะ พาวเวอร์สูทนี่เป็นรุ่นอัปเกรดของที่ไอ้พวกแบล็กไทด์ใส่กัน"
L31_1.m_Talk_THA = L32_1
L32_1 = "Nói để cô nhớ, bộ giáp sức mạnh này là phiên bản nâng cấp của bộ giáp mà bọn lợn ngốc Hắc Triều đã mặc."
L31_1.m_Talk_VTN = L32_1
L32_1 = "可以提前告诉你，我身上的改良型强化服比黑潮使用过的更完美。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Und fürs Protokoll: Dieser Poweranzug ist eine verbesserte Version dessen, was diese „Black Tide“-Schweine tragen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Oh et au cas où tu voudrais tenter quelque chose de stupide, sache que ma combinaison est une version renforcée du modèle porté par ces imbéciles de Black Tide."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "HORIZON_ACT2_STAGE3_START@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3500208
L32_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "BOSS_HORIZON_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "네가 어지간한 카운터라도 손모가지를 가볍게 부러뜨릴 수 있지."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "お前がよほど強いカウンターでも、手首を折ってやることぐらい簡単ってことさ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Meaning we can snap your arm without even trying, Counter or not."
L32_1.m_Talk_ENG = L33_1
L33_1 = "就算你是能力還不錯的制裁者，我也可以輕鬆折斷你的手腕。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ซึ่งแปลว่าไม่ว่าเธอจะเป็นเคาน์เตอร์หรือไม่ เราก็หักแขนเธอได้ง่ายๆ เลย"
L32_1.m_Talk_THA = L33_1
L33_1 = "Có nghĩa là chúng tôi có thể kẹp nát cánh tay cô mà chẳng cần phải tốn sức, dù cô có là Counter hay không."
L32_1.m_Talk_VTN = L33_1
L33_1 = "就算你是制裁者，也能轻易将你的手脚打断。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Das heißt, wir können dir die Hand verdrehen, wenn es nötig ist. Egal, ob Counter oder nicht."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Counter ou pas, je n'ai pas besoin de forcer pour te casser le bras."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "HORIZON_ACT2_STAGE3_START@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3500208
L33_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L33_1.m_bWaitClick = false
L33_1.m_fWaitTime = 0
L34_1 = "BOSS_HORIZON_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "저항은 포기하고 얌전히 구는 게……"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "抵抗は諦めて大人しく……"
L33_1.m_Talk_JPN = L34_1
L34_1 = "So I suggest you come along quietly or-"
L33_1.m_Talk_ENG = L34_1
L34_1 = "我勸你還是放棄抵抗，乖乖地……"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เพราะงั้น ขอแนะนำให้ตามมาเงียบๆ ดีกว่า ไม่งั้น-"
L33_1.m_Talk_THA = L34_1
L34_1 = "Vì vậy, tôi đề nghị cô hãy ngoan ngoãn mà đi theo, nếu không thì-"
L33_1.m_Talk_VTN = L34_1
L34_1 = "劝你还是放弃抵抗……"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Also schlage ich vor, dass du leise mitkommst, oder ..."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Alors tu vas nous suivre bien gentiment, ou..."
L33_1.m_Talk_FRA = L34_1
