L37_1 = "HORIZON_ACT2_STAGE3_START@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3500208
L36_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L37_1 = "커뮤니케이션을 시작합니다. 비협조적인 태도로 응할 경우 설득하겠으니 양해 바랍니다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "コミュニケーションを開始します。非協力的な態度で応じる場合、説得しますのでご了承ください。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "I will now commence my inquiries. Refusal to cooperate will be met with more persuasive measures. Thank you for your understanding."
L36_1.m_Talk_ENG = L37_1
L37_1 = "現在開始溝通，如果出現不配合態度，就會立刻說服你，還請諒解。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฉันจะดำเนินการสอบถาม ณ บัดนี้นะคะ การไม่ให้ความร่วมมือจะนำไปสู่มาตรการที่ให้ความโน้มน้าวใจยิ่งขึ้น ขอขอบคุณในความเข้าใจที่มีให้ค่ะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Bây giờ tôi sẽ bắt đầu các câu hỏi của mình. Việc từ chối hợp tác sẽ được đáp trả bằng các biện pháp thuyết phục hơn. Cảm ơn các anh đã hiểu."
L36_1.m_Talk_VTN = L37_1
L37_1 = "现在开始沟通。如果出现非协助性态度将继续进行说服，请谅解。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ich beginne jetzt mit der Kommunikation. Die Verweigerung der Zusammenarbeit wird mit Maßnahmen beantwortet. Habt Verständnis."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Début de l'interrogatoire. Tout refus de coopérer entraînera la prise de mesures persuasives, merci de votre compréhension."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "HORIZON_ACT2_STAGE3_START@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3500208
L37_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L38_1 = "윌버가 레이첼을 공격하라고 지시했습니까, 휴먼?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "ウィルバーがレイチェルを攻撃しろと指示しましたか、ヒューマン？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Has Wilbur ordered you humans to attack Rachel?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "人類，是韋爾伯指使你攻擊瑞秋的嗎？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "วิลเบอร์สั่งให้มนุษย์อย่างพวกคุณโจมตีเรเชลเหรอคะ?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Wilbur đã ra lệnh cho các người tấn công Rachel ư?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "是韦尔伯指使你攻击雷切尔的吗，人类？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Hat Wilbur euch befohlen, Rachel anzugreifen?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Est-ce Wilbur qui vous a donné l'ordre d'attaquer Rachel, humain ?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
