L41_1 = "카하아악!? 파, 팔이 부러졌어! 내 팔이 부러졌다고!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "ぐわああっ！！　う、腕が折れた！　俺の腕が！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Ack…!? M-my arm! You broke my arm!"
L40_1.m_Talk_ENG = L41_1
L41_1 = "啊啊啊啊！？手…我的手要斷了！手要斷了啦！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "อัก...!? ขะ-แขนฉัน! แกหักแขนฉันแล้ว!"
L40_1.m_Talk_THA = L41_1
L41_1 = "Ack… !? C-cánh tay của tôi! Cô đã làm gãy tay tôi!"
L40_1.m_Talk_VTN = L41_1
L41_1 = "呃啊啊啊！胳、胳膊断了！我的胳膊断了！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Ach ...!? M-mein Arm! Du hast mir den Arm gebrochen!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Aaaaah ! M-Mon bras ! Elle a cassé mon bras !"
L40_1.m_Talk_FRA = L41_1
