L42_1 = "다시 묻겠습니다, 휴먼. 윌버가 지시했습니까?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "もう一度聞きます、ヒューマン。ウィルバーが指示しましたか？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I repeat. Did Wilbur give the order?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "人類，我再問你一次，是韋爾伯指使你的嗎？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ถามอีกครั้งนะคะ วิลเบอร์สั่งมารึเปล่าคะ?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tôi lặp lại. Có phải Wilbur đã ra lệnh không?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "我再问你一次，人类。是韦尔伯指使的吗？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ich wiederhole. Hat Wilbur den Befehl gegeben?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Je réitère ma question : Wilbur a-t-il donné l'ordre ?"
L41_1.m_Talk_FRA = L42_1
