L42_1.m_Talk_THA = L43_1
L43_1 = "Đừng chỉ đứng đó! Loại bỏ cô ta đi! Làm ngay đi!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "别光看着啊！快拉开！快把她拉开！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Steh nicht nur da! Schaff sie mir vom Hals! Jetzt sofort!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Qu'est-ce que vous foutez, vous autres ? Restez pas assis là et emparez-vous d'elle !"
