L47_1.m_CharStrID = L48_1
L48_1 = "뭐, 뭐야?! 강화복 출력이 최대인데 꿈쩍도 안 해!"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "な、なんだ！？　強化服の出力が最大値なのにびくともしない！"
L47_1.m_Talk_JPN = L48_1
L48_1 = "W-what the?! I've set the power suit at max output but she still won't budge!"
L47_1.m_Talk_ENG = L48_1
L48_1 = "這…這是怎樣？！強化服輸出已經達到最大值，卻毫無招架之力！"
L47_1.m_Talk_TWN = L48_1
L48_1 = "อะ-อะไรวะ?! ฉันตั้งเอาต์พุตพาวเวอร์สูทสูงสุดแล้วแต่เธอยังไม่ขยับเลย!"
L47_1.m_Talk_THA = L48_1
L48_1 = "C-cái gì vậy?! Mình đã cài đặt bộ giáp sức mạnh ở công suất tối đa nhưng cô ta vẫn chẳng hề hấn gì!"
L47_1.m_Talk_VTN = L48_1
L48_1 = "怎、怎么可能？！强化服的输出已经是最大值了，为什么掰不动！"
L47_1.m_Talk_SCN = L48_1
L48_1 = "W-was zum?! Ich habe den Poweranzug auf maximale Leistung eingestellt, aber sie rührt sich immer noch nicht!"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Q-Quoi ? Ma combinaison est à puissance maximale, pourquoi je peux pas bouger ?"
L47_1.m_Talk_FRA = L48_1
