L1_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L2_1 = "척추 골절 및 내출혈 감지. 대출 상담은 번호표를 받은 후 대기하여 주십시오."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "脊椎骨折および内出血の感知。貸付相談は番号札を受け取り、待機してください。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Spinal fracture and internal bleeding detected. Please take a number and wait for your loan application. I'll be right with you."
L1_1.m_Talk_ENG = L2_1
L2_1 = "感應到脊椎骨折和內出血。有資金需求，請抽號碼牌等候叫號。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ตรวจพบการแตกหักของกระดูกสันหลังและเลือดออกภายใน โปรดรับบัตรคิวและรอการสมัครกู้ยืมของคุณ สักครู่ฉันจะไปพบค่ะ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Đã phát hiện gãy cột sống và chảy máu trong. Hãy lấy số và chờ nhận hồ sơ vay. Tôi sẽ chờ các anh."
L1_1.m_Talk_VTN = L2_1
L2_1 = "检测到脊椎骨折以及内出血。如需商谈贷款请先叫号后排队等待。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Wirbelsäulenfraktur und innere Blutungen festgestellt. Bitte ziehen Sie eine Nummer und warten Sie auf Ihren Kreditantrag. Ich bin gleich bei Ihnen."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Fracture de la colonne vertébrale et hémorragies internes détectées. Pour une demande de crédit, prenez un numéro et attendez votre tour."
L1_1.m_Talk_FRA = L2_1
