L3_1 = "HORIZON_ACT2_STAGE3_START@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3500208
L2_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L3_1 = "다시 묻겠습니다. 윌버가 지시했습니까?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "もう一度聞きます。ウィルバーが指示しましたか？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "I repeat. Did Wilbur give the order?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "我再問你一次，是韋爾伯指使你的嗎？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ถามอีกครั้งนะคะ วิลเบอร์สั่งมารึเปล่าคะ?"
L2_1.m_Talk_THA = L3_1
L3_1 = "Tôi lặp lại. Wilbur có ra lệnh không?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "我再问你一次。是韦尔伯指使的吗？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Ich frage noch einmal. Hat Wilbur den Befehl gegeben?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Je réitère ma question : Wilbur a-t-il donné l'ordre ?"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "HORIZON_ACT2_STAGE3_START@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3500208
