L4_1 = "MBOSS_HORIZON_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "빌어먹을 계집애가아아……! 여기 지금 몇 명이나 진을 치고 있는지 알아!?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "このクソ女が……！　ここにお前の敵が何人いるかわかってんのか！？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "You crazy bxxch! You got any idea how many of us are here?!"
L3_1.m_Talk_ENG = L4_1
L4_1 = "該死的臭丫頭……！你知道我們安排多少人在這裡嗎！？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ยัยบ้านี่! รู้หินรู้แดดบ้างมั้ยว่าพวกเรามีกันกี่คนน่ะ?!"
L3_1.m_Talk_THA = L4_1
L4_1 = "Đồ điên! Mày có biết bọn tao có bao nhiêu người ở đây không?!"
L3_1.m_Talk_VTN = L4_1
L4_1 = "臭丫头……！你知道我们在附近安排了多少人吗！？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Du verrücktes Weib ...! Hast du eine Ahnung, wie viele von uns hier sind?!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Espèce de sale @#$% ! Tu sais combien on est, au moins ?"
L3_1.m_Talk_FRA = L4_1
