L13_1 = 0.81
L11_1[L12_1] = L13_1
L12_1 = "BOSS_HORIZON_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "개틀링, 아니야, 미사일! 미사일을 날려! 어서!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ガトリング、いや、ミサイル！　ミサイルを撃て！　はやく！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Requesting a close air support strafe… wait, scrap that! A missile! Just shoot a damn missile! Now!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "發射加特林…不，導彈！發射導彈！快！！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ขอการยิงกราดจากกำลังสนับสนุนทางอากาศในระยะประชิด... เดี๋ยวนะ ไม่เอาละ! มิสไซล์! ยิงมิสไซล์มาโว้ย! เดี๋ยวนี้!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Yêu cầu hỗ trợ không lực gần... khoan đã, bỏ đi! Một tên lửa! Chỉ cần bắn một tên lửa chết tiệt! Ngay bây giờ!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "使用加特林，不，使用导弹！快发射导弹！快！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Luftnahunterstütz... nein, eine Rakete! Schießt einfach eine verdammte Rakete! Sofort!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Mitraillage au sol... Non, bombardement d'urgence requis ! Envoyez un missile !"
L11_1.m_Talk_FRA = L12_1
