L13_1 = "MOB_HORIZON_NULL_NULL"
L12_1.m_CharStrID = L13_1
L13_1 = "당신 미쳤어?! 그러다 우리 다 죽는다고!"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "あんた正気か！？　そんなことしたら全員死ぬぞ！？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Are you out of your mind?! You’ll get us all killed!"
L12_1.m_Talk_ENG = L13_1
L13_1 = "你瘋啦？！這樣我們全都會死！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "บ้าไปแล้วเหรอครับ?! เราจะตายกันหมดนะครับ!"
L12_1.m_Talk_THA = L13_1
L13_1 = "Anh mất trí rồi à?! Anh sẽ giết tất cả chúng ta mất!"
L12_1.m_Talk_VTN = L13_1
L13_1 = "你疯了吗？！如果这样我们都会死！"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Bist du von Sinnen?! Du bringst uns alle um!"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Un missile ? Mais vous êtes fou, on va tous mourir !!"
L12_1.m_Talk_FRA = L13_1
