L14_1 = "HELI_TIDE_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "<color=#ffd34c>위험사격 판단 알고리즘 해제. 추가 적재된 대전차 미사일을 발사합니다.</color>"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "<color=#ffd34c>危険射撃判断アルゴリズム解除。追加積載された対戦車ミサイルを発射します。</color>"
L13_1.m_Talk_JPN = L14_1
L14_1 = "<color=#ffd34c>Overriding danger-close protocol. Launching the extra payload of anti-tank missiles.</color>"
L13_1.m_Talk_ENG = L14_1
L14_1 = "<color=#ffd34c>解除危險射擊判斷演算法。發射追加裝載的反坦克導彈。</color>"
L13_1.m_Talk_TWN = L14_1
L14_1 = "<color=#ffd34c>กำลังโอเวอร์ไรด์โปรโตคอลประชิดอันตราย กำลังปล่อยมิสไซล์ต่อต้านรถถังปริมาณพิเศษ</color>"
L13_1.m_Talk_THA = L14_1
L14_1 = "<color=#ffd34c>Ghi đè giao thức cận nguy hiểm. Đang phóng thêm trọng tải tên lửa chống tăng.</color>"
L13_1.m_Talk_VTN = L14_1
L14_1 = "<color=#ffd34c>危险射击判断计算程式已解除锁定。将发射搭载的对战车导弹。</color>"
L13_1.m_Talk_SCN = L14_1
L14_1 = "<color=#ffd34c>Übergehen des Gefahrenschuss-Protokolls. Abschuss der zusätzlichen Nutzlast von Panzerabwehrraketen.</color>"
L13_1.m_Talk_DEU = L14_1
L14_1 = "<color=#ffd34c>Outrepassement du protocole de sécurité. Chargement des ogives antichar.</color>"
L13_1.m_Talk_FRA = L14_1
