L22_1.m_Talk_ENG = L23_1
L23_1 = "嗚嗚……嗚嗚嗚嗚……！瘋……！你這瘋……！"
L22_1.m_Talk_TWN = L23_1
L23_1 = "พรวด! อึ๊ก... ว้ากกกก! แกนี่มัน... บ้าทุกเม็ดเลย...!!"
