L24_1 = "HORIZON_ACT2_STAGE3_START@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3500208
L23_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L24_1 = "실시간으로 생체정보를 확인하면서 치명상을 예방 중입니다. 대답하기 전까지 죽을 일은 없을 겁니다."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "リアルタイムで生体情報を確認しながら致命傷を予防しています。答えるまで死ぬことはないでしょう。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I'm monitoring your vital signs in real time to avoid any fatal injuries. You will not die until I have my answer."
L23_1.m_Talk_ENG = L24_1
L24_1 = "我會一邊確認生命指數，一邊避免致命傷。所以在你回答之前，是死不了的。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ฉันกำลังตรวจสอบสัญญาณชีพคุณแบบเรียลไทม์จะได้ไม่บาดเจ็บถึงตายนะคะ ถ้าฉันไม่ได้คำตอบคุณก็จะยังตายไม่ได้ค่ะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Tôi đang theo dõi các dấu hiệu sinh tồn quan trọng của anh trong thời gian thực để tránh bất kỳ thương tích chết người nào. Anh sẽ không chết cho đến khi tôi có câu trả lời của mình."
L23_1.m_Talk_VTN = L24_1
L24_1 = "我会实时监控你的生物信息防止出现致命伤害。在你回答之前没办法死掉。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Ich überwache eure Vitalfunktionen in Echtzeit, um tödliche Verletzungen zu vermeiden. Du wirst nicht sterben, bis ich meine Antwort habe."
L23_1.m_Talk_DEU = L24_1
L24_1 = "J'ai vos signes vitaux en visuel pour éviter les blessures fatales. Vous ne mourrez pas avant que j'obtienne mes réponses."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "HORIZON_ACT2_STAGE3_START@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3500208
L24_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L25_1 = "저희 회사를 거쳐 간 채무불이행자들을 통해 검증된 프로세스이니 안심하시죠."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "当社の複数の債務不履行者によって検証されたプロセスなので、ご安心ください。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "You can rest assured this process has been rigorously tested upon my company's former clients."
L24_1.m_Talk_ENG = L25_1
L25_1 = "這套處理流程，有由公司經手的那些不履行債務人驗證過，你可以放心。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "สบายใจได้เลยนะคะว่ากระบวนการนี้ผ่านการทดสอบอย่างเข้มงวดมากับพวกอดีตลูกค้าของฉันแล้วค่ะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Anh có thể yên tâm rằng quy trình này đã được kiểm tra nghiêm ngặt trên các khách hàng cũ của công ty tôi."
L24_1.m_Talk_VTN = L25_1
L25_1 = "这是我们公司通过不履行债务者验证过的程序，你可以放心。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Du kannst dir sicher sein, dass dieser Vorgang von ehemaligen, nicht zahlenden Kunden meines Unternehmens streng getestet wurde."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Vous n'avez pas à vous inquiéter, ce protocole a déjà fait l'objet de tests rigoureux auprès de mes anciens clients."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
