L27_1 = "BOSS_HORIZON_NULL_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "어, 엄마…… 엄마, 살려 줘, 엄마…… 엄마……!"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "た、助けて……助けて……ください……おねがい……！"
L26_1.m_Talk_JPN = L27_1
L27_1 = "M-mommy… I don't wanna die… Mommy…!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "嗚…媽媽……媽媽救我……媽媽……！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "มะ-แม่จ๋า... หนูยังไม่อยากตาย... แม๊...!"
L26_1.m_Talk_THA = L27_1
L27_1 = "M-mẹ ơi… Con không muốn chết… Mẹ ơi…!"
L26_1.m_Talk_VTN = L27_1
L27_1 = "啊，妈妈……妈妈，救救我，妈妈……妈妈……！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "M-Mama ... Mama, Hilfe, Mama ...!"
L26_1.m_Talk_DEU = L27_1
L27_1 = "M-Maman... Pitié.... Je ne veux pas mourir ! Maman...!"
L26_1.m_Talk_FRA = L27_1
