L31_1 = "BOSS_HORIZON_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "끄하악……! 살려 줘……! 엄마아아아!!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ぐはああっ……！　おねがい……します……！　助けてえええ！！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Eeek…! Don't kill me! Mommyyyy!!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "呃啊啊……！救我……！媽媽！！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "แว้ก...! อย่าฆ่าหนูเลย! แแแแแแม๊!!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Eeek…! Đừng giết tôi! Mẹ ơiiiiiiiii!!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "呃啊啊……！救救我……！妈妈啊啊啊！！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Uwaargh ...! Töte mich nicht! Mamaaa!!!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Aaah ! Épargnez-moi...! Mamannn !!"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "HORIZON_ACT2_STAGE3_START@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3500208
L31_1.m_CutScenStrID = "HORIZON_ACT2_STAGE3_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L32_1 = "저는 당신 엄마가 아닙니다. 휴먼. 입원 기간을 늘리기 싫으면 질문에나 대답하십시오."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "答えないと助かりません、ヒューマン。これ以上傷を増やしたくなければ質問に答えてください。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I am not your mother, human. I suggest you answer my question if you do not wish to extend your stay at the hospital any further."
L31_1.m_Talk_ENG = L32_1
L32_1 = "我不是你媽媽。人類，如果你不想延誤就醫，就請回答問題。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ฉันไม่ใช่แม่คุณนะคะ คุณมนุษย์ และถ้าไม่อยากนอนโรงพยาบาลนานกว่านี้ ก็ขอแนะให้ตอบคำถามของฉันมาดีๆ ค่ะ คุณมนุษย์"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi không phải là mẹ của anh, con người. Tôi đề nghị anh trả lời câu hỏi của tôi nếu anh không muốn kéo dài thời gian nằm viện thêm nữa."
L31_1.m_Talk_VTN = L32_1
L32_1 = "我不是你的妈妈。人类。如果不想一辈子住在医院里，就回答我的问题。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich bin nicht deine Mutter, Mensch. Ich schlage vor, du beantwortest meine Frage, wenn du deinen Aufenthalt im Krankenhaus nicht weiter verlängern möchtest."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Je ne suis pas votre mère, humain. Si vous ne voulez pas passer le restant de vos jours dans un lit d'hôpital, je vous suggère de faire ce que je vous dis."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "HORIZON_ACT2_STAGE3_START@182#Talk"
