L32_1.m_StartFXSoundName = "FX_CUTSCEN_BEEP"
L33_1 = "<color=#ffd34c>적대 개체 다수 감지. 포위망을 형성하고 있습니다.</color>"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "<color=#ffd34c>敵性個体複数感知。包囲網を形成しています。</color>"
L32_1.m_Talk_JPN = L33_1
L33_1 = "<color=#ffd34c>Multiple hostiles detected. They have surrounded the site.</color>"
L32_1.m_Talk_ENG = L33_1
L33_1 = "<color=#ffd34c>感應到多數敵對個體，形成防護網中。</color>"
L32_1.m_Talk_TWN = L33_1
L33_1 = "<color=#ffd34c>ตรวจพบศัตรูหลายหน่วย พวกมันล้อมพื้นที่นี้ไว้แล้ว</color>"
L32_1.m_Talk_THA = L33_1
L33_1 = "<color=#ffd34c>Đã phát hiện nhiều kẻ thù. Họ đã bao vây địa điểm.</color>"
L32_1.m_Talk_VTN = L33_1
L33_1 = "<color=#ffd34c>检测到多个敌对目标。正在形成包围。</color>"
L32_1.m_Talk_SCN = L33_1
L33_1 = "<color=#ffd34c>Mehrere Feinde entdeckt. Umzingelung im Gange.</color>"
L32_1.m_Talk_DEU = L33_1
L33_1 = "<color=#ffd34c>Corps hostiles détectés. Ils ont encerclé le périmètre.</color>"
L32_1.m_Talk_FRA = L33_1
